Algorithme DemoActionsAvecPointeurs;
Var
    x, y, grand : Entier;
    px, py : ^Entier;

Fonction Max2(a, b : Entier) : Entier
Debut
    Si (a >= b) Alors
        Retourner a;
    Sinon
        Retourner b;
    Fin Si;
Fin;

Procedure Echanger(a : ^Entier; b : ^Entier)
Var
    temp : Entier;
Debut
    temp := a^;
    a^ := b^;
    b^ := temp;
Fin;

Debut
    x := 15; y := 42;

    // Appel de la Fonction Max2
    grand := Max2(x, y);
    Ecrire("Le plus grand est : ", grand); // Affiche 42

    // Allocation ou passage des pointeurs pour l'échange par adresse
    px := allouer(taille(Entier));
    py := allouer(taille(Entier));
    px^ := x; py^ := y;

    Echanger(px, py);
    Ecrire("Après échange : px^ = ", px^, " et py^ = ", py^); // px^=42, py^=15 !

    liberer(px); liberer(py);
Fin.
